public function delete_cache($uri = '')
{
    $CI =& get_instance();
    $cache_path = $CI->config->item('cache_path');
    if ($cache_path === '') {
        $cache_path = APPPATH . 'cache/';
    }

    if (!is_dir($cache_path)) {
        log_message('error', 'Unable to find cache path: ' . $cache_path);
        return FALSE;
